use std::io::{self, BufRead};
fn main() { for line in io::stdin().lock().lines() {let s=line.unwrap(); let token=if let Some(h)=s.strip_prefix("bits:"){let bits=u64::from_str_radix(h,16).unwrap();serde_json::to_string(&f64::from_bits(bits)).unwrap()}else{s};match serde_json::from_str::<serde_json::Value>(&token) { Ok(v) => println!("{}",serde_json::json!({"token":token,"i64":v.as_i64(),"u64":v.as_u64(),"f64_bits":v.as_f64().map(|f|format!("{:016x}",f.to_bits())),"float":v.is_f64(),"serialized":v.to_string()})),Err(e)=>println!("{}",serde_json::json!({"token":token,"error":e.to_string()}))}}}
